package store

import (
	"fmt"
	"regexp"
	"strings"
	"time"

	"github.com/galileostudio/baleia/internal/store/model"
	"github.com/google/uuid"
	"gorm.io/gorm"
	"gorm.io/gorm/clause"
	"gorm.io/gorm/schema"
)

// Models is the authoritative store schema (ADR 0020): one GORM model per
// table, with tags and associations.
func Models() []any { return model.All() }

// AutoMigrate creates or reconciles the schema for models. On MySQL/MariaDB it
// first drops PostgreSQL-only defaults that the models declare, such as
// gen_random_uuid(); IDs there are generated by the application.
func AutoMigrate(db *gorm.DB, models ...any) error {
	all := append(append([]any{}, models...), Models()...)
	if err := prepareModels(db, all); err != nil {
		return err
	}
	if err := db.AutoMigrate(models...); err != nil {
		return err
	}
	return createForeignKeys(db, models)
}

// createForeignKeys adds the belongs-to constraints once every table exists.
// AutoMigrate runs with DisableForeignKeyConstraintWhenMigrating, because GORM
// otherwise inlines a constraint whose referenced table may not exist yet.
func createForeignKeys(db *gorm.DB, models []any) error {
	for _, m := range models {
		stmt := &gorm.Statement{DB: db}
		if err := stmt.Parse(m); err != nil {
			return err
		}
		for name, rel := range stmt.Schema.Relationships.Relations {
			if rel.Type != schema.BelongsTo {
				continue
			}
			if db.Migrator().HasConstraint(m, name) {
				continue
			}
			if err := db.Migrator().CreateConstraint(m, name); err != nil {
				return fmt.Errorf("create foreign key %s on %T: %w", name, m, err)
			}
		}
	}
	return nil
}

// prepareModels mutates GORM's parsed schema before migration so a
// PostgreSQL-only default is not emitted on MySQL/MariaDB. The parse cache is
// shared with AutoMigrate, so the change applies to the DDL it builds.
func prepareModels(db *gorm.DB, models []any) error {
	if db.Name() != "mysql" {
		return nil
	}
	for _, m := range models {
		stmt := &gorm.Statement{DB: db}
		if err := stmt.Parse(m); err != nil {
			return err
		}
		setNullCols := setNullColumns(stmt.Schema)
		for _, field := range stmt.Schema.Fields {
			if field.DefaultValue == "gen_random_uuid()" {
				field.DefaultValue = ""
				field.HasDefaultValue = false
			}
			if chk := field.TagSettings["CHECK"]; chk != "" {
				translated := translateMySQLCheck(chk)
				if translated != "" && referencesAny(translated, setNullCols) {
					// MySQL rejects a check that touches a column with a
					// SET NULL referential action.
					translated = ""
				}
				if translated != "" {
					field.TagSettings["CHECK"] = translated
				} else {
					delete(field.TagSettings, "CHECK")
				}
			}
		}
	}
	return nil
}

// setNullColumns lists the foreign-key columns whose constraint uses ON DELETE
// SET NULL, which MySQL forbids in a check constraint.
func setNullColumns(s *schema.Schema) map[string]bool {
	out := map[string]bool{}
	for _, rel := range s.Relationships.Relations {
		if !strings.Contains(strings.ToUpper(rel.Field.TagSettings["CONSTRAINT"]), "SET NULL") {
			continue
		}
		for _, ref := range rel.References {
			if ref.ForeignKey != nil {
				out[ref.ForeignKey.DBName] = true
			}
		}
	}
	return out
}

func referencesAny(expr string, cols map[string]bool) bool {
	for col := range cols {
		if regexp.MustCompile(`\b` + regexp.QuoteMeta(col) + `\b`).MatchString(expr) {
			return true
		}
	}
	return false
}

var (
	castRE    = regexp.MustCompile(`::[a-zA-Z_][\w\[\]"]*`)
	anyRE     = regexp.MustCompile(`([\w.]+)\s*=\s*ANY\s*\(\s*ARRAY\[([^\]]*)\]\s*\)`)
	allRE     = regexp.MustCompile(`([\w.]+)\s*<>\s*ALL\s*\(\s*ARRAY\[([^\]]*)\]\s*\)`)
	triggerRE = regexp.MustCompile(`\btrigger\b`)
	roleRE    = regexp.MustCompile(`\brole\b`)
	bareRE    = regexp.MustCompile(`^[a-zA-Z_]\w*$`)
)

// translateMySQLCheck rewrites the PostgreSQL-only parts of a check expression,
// or returns "" when the expression has no MySQL equivalent (array containment,
// for example). The check name is preserved.
func translateMySQLCheck(chk string) string {
	name, expr, ok := strings.Cut(chk, ",")
	if !ok {
		return chk
	}
	expr = castRE.ReplaceAllString(expr, "")
	expr = anyRE.ReplaceAllString(expr, "$1 IN ($2)")
	expr = allRE.ReplaceAllString(expr, "$1 NOT IN ($2)")
	// MySQL rejects a bare boolean column as a CHECK expression.
	core := strings.TrimSpace(expr)
	for strings.HasPrefix(core, "(") && strings.HasSuffix(core, ")") {
		core = strings.TrimSpace(core[1 : len(core)-1])
	}
	if bareRE.MatchString(core) {
		expr = core + " = TRUE"
	}
	expr = strings.ReplaceAll(expr, "!~~", "NOT LIKE")
	expr = strings.ReplaceAll(expr, "~~", "LIKE")
	expr = strings.ReplaceAll(expr, "!~", "NOT REGEXP")
	expr = strings.ReplaceAll(expr, "~", "REGEXP")
	for _, unsupported := range []string{"<@", "@>", "ARRAY[", "ANY", "ALL", "::", "tsvector"} {
		if strings.Contains(expr, unsupported) {
			return ""
		}
	}
	if strings.Contains(expr, "REGEXP") && strings.Contains(expr, `\`) {
		// MariaDB rejects a pattern with a lone trailing backslash.
		return ""
	}
	// MySQL reserves these words, and the check expressions name columns raw.
	expr = triggerRE.ReplaceAllString(expr, "`trigger`")
	expr = roleRE.ReplaceAllString(expr, "`role`")
	return name + "," + expr
}

// AllMigrations is the versioned schema registry. Additive transitions call
// AutoMigrate over Models; destructive or renaming transitions use GORM's
// Migrator inside their own versioned entry.
func AllMigrations() (*Registry, error) {
	return NewRegistry(
		Migration{
			Version: 1,
			Name:    "create store schema",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, Models()...)
			},
		},
		Migration{
			Version: 2,
			Name:    "create setup locks",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.SetupLock{})
			},
		},
		Migration{
			Version: 3,
			Name:    "add metadata sync heartbeat",
			Up: func(db *gorm.DB) error {
				return AutoMigrate(db, &model.MetadataSyncRun{})
			},
		},
		Migration{
			Version: 4,
			Name:    "seed store defaults",
			Up:      seedDefaults,
		},
	)
}

// seedDefaults creates the rows a fresh goose database used to seed: the
// default Trino cluster and its federated engine, and the assistant settings
// singleton. Existing rows are left untouched, so the migration is safe on an
// adopted database.
func seedDefaults(db *gorm.DB) error {
	now := time.Now().UTC()
	cluster := model.TrinoCluster{
		ID:             model.UUID(uuid.NewString()),
		Name:           model.Text("default"),
		CoordinatorURL: "http://trino:8080",
		CreatedAt:      now,
	}
	if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&cluster).Error; err != nil {
		return fmt.Errorf("seed default trino cluster: %w", err)
	}
	if err := db.Where("name = ?", "default").First(&cluster).Error; err != nil {
		return fmt.Errorf("read default trino cluster: %w", err)
	}
	if cluster.EngineID == nil {
		conn := model.CatalogConnection{
			ID:        model.UUID(uuid.NewString()),
			Name:      model.Text("trino-default"),
			Type:      "trino",
			URL:       "http://trino:8080",
			Config:    model.JSON(`{"url":"http://trino:8080"}`),
			CreatedAt: now,
			UpdatedAt: now,
		}
		if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&conn).Error; err != nil {
			return fmt.Errorf("seed trino connection: %w", err)
		}
		if err := db.Where("name = ?", "trino-default").First(&conn).Error; err != nil {
			return fmt.Errorf("read trino connection: %w", err)
		}
		engine := model.Engine{
			ID:           model.UUID(uuid.NewString()),
			Name:         model.Text("default"),
			Kind:         "trino",
			Class:        "federated",
			ConnectionID: conn.ID,
			IdentityMode: model.Text("impersonation"),
			Enabled:      true,
			CreatedAt:    now,
			UpdatedAt:    now,
		}
		if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&engine).Error; err != nil {
			return fmt.Errorf("seed trino engine: %w", err)
		}
		if err := db.Where("name = ?", "default").First(&engine).Error; err != nil {
			return fmt.Errorf("read trino engine: %w", err)
		}
		if err := db.Model(&model.TrinoCluster{}).Where("id = ?", string(cluster.ID)).
			Update("engine_id", engine.ID).Error; err != nil {
			return fmt.Errorf("link default trino engine: %w", err)
		}
	}
	settings := model.AssistantSetting{ID: true}
	if err := db.Clauses(clause.OnConflict{DoNothing: true}).Create(&settings).Error; err != nil {
		return fmt.Errorf("seed assistant settings: %w", err)
	}
	return nil
}
